import { useRef, useState } from 'react';
import { useScrollFragments } from '../components/useScrollFragments.js';
import { Link, useParams } from 'react-router-dom';
import { FragmentChirp } from './feed.jsx';
import { applyPostPreferences } from '../data/postPreferences.js';
import MediaUploadModal from '../components/MediaUploadModal.jsx';
import MentionSuggestions from '../components/MentionSuggestions.jsx';
import MentionTextarea from '../components/MentionTextarea.jsx';
import { useSocial } from '../features/social/SocialStore.jsx';

export default function Groups({ currentUser, users = [], groups = [], onCreateGroup, onUpdateGroup, onJoinGroup, onLeaveGroup, localChirps = [], onCreateChirp, postPreferences, appearancesByUid, onSavePost }) {
  const { groupId } = useParams();
  const social = useSocial();
  const [name, setName] = useState(''), [description, setDescription] = useState(''), [rules, setRules] = useState(''), [privateGroup, setPrivateGroup] = useState(false);
  const [search, setSearch] = useState(''), [draft, setDraft] = useState(''), [caret, setCaret] = useState(0);
  const [origin, setOrigin] = useState(null), [tab, setTab] = useState('posts'), [editMode, setEditMode] = useState(false);
  const groupPostsRef = useRef(null), draftRef = useRef(null);
  const group = groups.find(item => item.id === groupId);
  const isMember = !!group?.memberUids.some(uid => String(uid) === String(currentUser?.uid));
  const isOwner = !!group && String(group.ownerUid) === String(currentUser?.uid);
  const requested = !!group?.pendingMemberUids?.some(uid => String(uid) === String(currentUser?.uid));
  const posts = group ? applyPostPreferences(localChirps.filter(post => post.groupId === group.id && !(group.removedPostIds || []).includes(String(post.id))), postPreferences) : [];
  useScrollFragments(groupPostsRef, `${groupId}:${posts.map(post => post.id).join('|')}`);
  function send(event) { event.preventDefault(); if (!isMember || !draft.trim()) return; onCreateChirp(draft, { groupId: group.id }); setDraft(''); }
  function create(event) { event.preventDefault(); if (!name.trim()) return; onCreateGroup(name, description, { rules, private: privateGroup }); setName(''); setDescription(''); setRules(''); setPrivateGroup(false); }
  function manageRequests(uid, approve) { onUpdateGroup(group.id, { pendingMemberUids: (group.pendingMemberUids || []).filter(pending => String(pending) !== String(uid)), memberUids: approve ? [...new Set([...group.memberUids, uid])] : group.memberUids }); }
  return <main className="groups-page">
    <header className="groups-top"><Link className="feed-wordmark" to="/feed"><span className="feed-wordmark__icon" aria-hidden="true" /> chirpr<span>.</span></Link><nav><Link to="/feed">Feed</Link><Link to="/discover">Discover</Link><Link to="/reels">Reels</Link><Link to="/account">Profile</Link></nav></header>
    <div className="groups-shell"><div className="groups-hero"><span>✳ COMMUNITY / CHIRPR</span><h1>Find your <em>people.</em></h1><p>Spaces built around shared interests. Membership, posts and moderation actions are local prototypes until our backend is ready.</p></div>
      {!groupId ? <>
        <label className="groups-search"><span>⌕ Find your next community</span><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search group names or topics…" aria-label="Search groups" /></label>
        <section className="groups-grid">{groups.filter(item => `${item.name} ${item.description}`.toLowerCase().includes(search.toLowerCase())).map(item => <Link key={item.id} className="groups-tile" to={`/groups/${item.id}`}><span>{item.emoji}</span><strong>{item.name} {item.private ? '⌑' : ''}</strong><p>{item.description}</p><small>{item.memberUids.length} members <b>↗</b></small></Link>)}</section>
        <form className="groups-create" onSubmit={create}><span>✧ START A COMMUNITY</span><h2>Build your own corner.</h2><input required value={name} maxLength={60} onChange={e => setName(e.target.value)} placeholder="Group name" aria-label="Group name"/><textarea value={description} maxLength={240} onChange={e => setDescription(e.target.value)} placeholder="What brings your group together?" aria-label="Group description"/><textarea value={rules} maxLength={700} onChange={e => setRules(e.target.value)} placeholder="Set the tone: group rules (optional)" aria-label="Group rules"/><label className="groups-privacy"><input type="checkbox" checked={privateGroup} onChange={e => setPrivateGroup(e.target.checked)} />Private group — require membership approval</label><button type="submit" className="chirpr-hover-glow">Create group ↗</button></form>
      </> : !group ? <div className="groups-empty">Group not found. <Link to="/groups">Browse communities</Link></div> : <>
        <section className="groups-detail"><Link to="/groups">← All groups</Link><div><span>{group.emoji}</span><h2>{group.name}</h2></div><p>{group.description}</p><small>{group.memberUids.length} members · {group.private ? '⌑ Private group' : '✧ Public group'}</small>
          {!isMember && <button className="chirpr-hover-glow" type="button" disabled={requested} onClick={() => onJoinGroup(group.id)}>{requested ? '◷ Request pending' : group.private ? 'Request to join ＋' : 'Join group ＋'}</button>}
          {isMember && <span className="groups-member">✓ You're a member</span>}{isMember && !isOwner && <button type="button" className="groups-leave" onClick={() => onLeaveGroup(group.id)}>Leave group</button>}
          {isOwner && <button type="button" className="groups-leave" onClick={() => setEditMode(v => !v)}>{editMode ? 'Close group studio' : '⚙ Manage group'}</button>}
          {isOwner && editMode && <div className="groups-admin"><h3>✦ Group studio</h3><p>Your moderation controls are stored locally; a real system will verify roles server-side.</p><label>Group description<textarea defaultValue={group.description} id="group-desc-edit" maxLength={240}/></label><label>Group rules<textarea id="group-rules-edit" defaultValue={group.rules || ''} maxLength={700}/></label><label className="groups-privacy"><input type="checkbox" checked={!!group.private} onChange={e => onUpdateGroup(group.id, { private: e.target.checked })}/>Require approval for new members</label><button onClick={() => onUpdateGroup(group.id, { description: document.getElementById('group-desc-edit').value.slice(0,240), rules: document.getElementById('group-rules-edit').value.slice(0,700) })}>Save community details</button><h3>Membership requests</h3>{(group.pendingMemberUids || []).length ? group.pendingMemberUids.map(uid => <div className="groups-request" key={uid}>@{users.find(u => String(u.uid) === String(uid))?.username || uid}<button onClick={() => manageRequests(uid,true)}>✓ Approve</button><button onClick={() => manageRequests(uid,false)}>✕ Decline</button></div>) : <p>No pending requests.</p>}</div>}
        </section>
        <div className="groups-section-tabs" role="tablist" aria-label="Community sections">{['posts','members','rules'].map(item => <button role="tab" aria-selected={tab === item} key={item} className={tab === item ? 'is-active' : ''} onClick={() => setTab(item)}>{item}</button>)}</div>
        {tab === 'members' && <section className="groups-members"><b>COMMUNITY MEMBERS</b><div>{users.filter(user => group.memberUids.some(uid => String(uid) === String(user.uid))).map(user => <div key={user.uid}><Link to={`/users/${user.username}`}><span>{user.displayName?.[0] || '✳'}</span><small>@{user.username}{String(user.uid) === String(group.ownerUid) ? ' · Owner' : ''}</small></Link>{isOwner && String(user.uid) !== String(group.ownerUid) && <button onClick={() => onUpdateGroup(group.id, { memberUids: group.memberUids.filter(uid => String(uid) !== String(user.uid)) })}>Remove member</button>}</div>)}</div></section>}
        {tab === 'rules' && <div className="groups-rules"><h3>✧ Our community rules</h3><p>{group.rules || 'Be respectful, stay on topic, and make room for everyone.'}</p><Link to="/safety">Chirpr community safety →</Link></div>}
        {tab === 'posts' && <>
          {isMember && <form onSubmit={send} className="groups-composer"><label htmlFor="group-draft">Share with {group.name}</label><MentionTextarea ref={draftRef} id="group-draft" value={draft} maxLength={500} rows={3} onChange={e => { setDraft(e.target.value); setCaret(e.target.selectionStart); }} onKeyUp={e => setCaret(e.target.selectionStart)} placeholder="Start a conversation… #ideas @friends" /><MentionSuggestions text={draft} caret={caret} users={users} onSelect={(username, part) => { setDraft(t => t.slice(0,part.start) + `@${username} ` + t.slice(part.end)); const position = part.start + username.length + 2; setCaret(position); requestAnimationFrame(() => { draftRef.current?.focus(); draftRef.current?.setSelectionRange(position, position); }); }} /><div className="groups-composer__actions"><button type="button" onClick={e => setOrigin(e.currentTarget.getBoundingClientRect())}>▧ Add image / video</button><button type="submit" className="chirpr-hover-glow" disabled={!draft.trim()}>Post to group ↗</button></div></form>}
          {!isMember && group.private && <div className="groups-empty">This group's posts are for members only. Request access to participate.</div>}
          <div className="groups-posts" ref={groupPostsRef}>{(!group.private || isMember) && posts.length ? posts.map(post => <div key={post.id} className="groups-post-wrapper">{(group.pinnedPostIds || []).includes(String(post.id)) && <div className="groups-pinned-label">✦ Pinned by admin</div>}<FragmentChirp post={post} author={users.find(u => String(u.uid) === String(post.uid))} appearance={appearancesByUid[String(post.uid)]} liked={social?.liked(post.id)} onLike={() => social?.toggleLike(post)} saved={postPreferences.saved.includes(String(post.id))} onSave={onSavePost} viewerUid={currentUser?.uid} />{isOwner && <div className="groups-moderator-actions"><button onClick={() => { const isPinned = (group.pinnedPostIds || []).includes(String(post.id)); onUpdateGroup(group.id, { pinnedPostIds: isPinned ? group.pinnedPostIds.filter(id => id !== String(post.id)) : [...(group.pinnedPostIds || []), String(post.id)] }); }}>{(group.pinnedPostIds || []).includes(String(post.id)) ? 'Unpin' : '✦ Pin'}</button><button onClick={() => onUpdateGroup(group.id, { removedPostIds: [...new Set([...(group.removedPostIds || []), String(post.id)])] })}>Remove from group</button></div>}</div>) : (!group.private || isMember) && <div className="groups-empty">No posts here yet. Start the conversation. ✦</div>}</div>
        </>}
      </>}
    </div>
    {origin && group && <MediaUploadModal origin={origin} draft={draft} groupId={group.id} onClose={({ queued } = {}) => { setOrigin(null); if (queued) setDraft(''); }} onPublish={onCreateChirp} />}
  </main>;
}
